window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7b8398836d955876"]={"versions": [{"id": "FIG-7b8398836d955876", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines algorithmischen Einzelschritts der AUTOSAR E2E-Bibliothek (End-to-End Communication Protection) im Protokollkontext von <code>E2E_PXXProtect()</code>. Dargestellt wird die Steuerflusslogik zur Serialisierung des Sequenzzählers (<code>Counter</code>) in das zu schützende Daten-Bytestring.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Kontext/Funktion: <code>E2E_PXXProtect()</code></li>\n<li>Zustandsparameter / Quelle: <code>State-&gt;Counter</code> mit der Länge <code>PXXCOUNTER_LEN</code> (in Bytes)</li>\n<li>Ziel-Datenpuffer: Bytestring <code>Data</code></li>\n<li>Konfigurationsparameter / Offsets: <code>Offset</code>, <code>PXXCOUNTER_POS</code>, <code>PXXCOUNTER_LEN</code></li>\n<li>Notizen / Kommentare:</li>\n<li>Profil-Platzhaltererklärung: <code>\"XX\" indicates one specific E2E profile. Placeholder are defined on profile level.</code></li>\n<li>Speicherbereichsdefinition: <code>Parameter State -&gt; Counter has length PXXCOUNTER_LEN (in bytes). Bytes needs to be stored in Data at positions Offset + PXXCOUNTER_POS to Offset + PXXCOUNTER_POS + PXXCOUNTER_LEN - 1.</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Start über den Initialknoten (Initial Node).</li>\n<li>Übergang zum Aktionsknoten <code>Copy parameter State-&gt;Counter to bytestring Data in Big Endian order</code>: Der Zählerwert aus <code>State-&gt;Counter</code> wird byteweise in Big-Endian-Reihenfolge in das Bytestring <code>Data</code> kopiert. Die Zielpositionen erstrecken sich über den zusammenhängenden Indexbereich <code>Offset + PXXCOUNTER_POS</code> bis <code>Offset + PXXCOUNTER_POS + PXXCOUNTER_LEN - 1</code>.</li>\n<li>Direkter Übergang zum Endknoten (Activity Final Node).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorschrift gemäß Anforderung [PRS_E2E_02365] (zugehörig zu RS_E2E_08539). Für Entwickler von E2E-Treiber- und Plattformroutinen ist zwingend die Big-Endian-Bytereihenfolge bei der Serialisierung des Counters zu beachten, unabhängig von der nativen Byteorder der Host-CPU. Der Platzhalter <code>XX</code> steht für das jeweilige konkrete Profil (z. B. 01, 02, etc.), dessen profilbezogene Konstanten (<code>PXXCOUNTER_POS</code>, <code>PXXCOUNTER_LEN</code>) sowie der anwenderspezifische Basis-Offset (<code>Offset</code>) die genaue Byte-Position im Puffer <code>Data</code> determinieren.</p>"}, {"id": "FIG-3d8050c7c1ecb539", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines algorithmischen Einzelschritts der AUTOSAR E2E-Bibliothek (End-to-End Communication Protection) im Protokollkontext von <code>E2E_PXXProtect()</code>. Dargestellt wird die Steuerflusslogik zur Serialisierung des Sequenzzählers (<code>Counter</code>) in das zu schützende Daten-Bytestring.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Kontext/Funktion: <code>E2E_PXXProtect()</code></li>\n<li>Zustandsparameter / Quelle: <code>State-&gt;Counter</code> mit der Länge <code>PXXCOUNTER_LEN</code> (in Bytes)</li>\n<li>Ziel-Datenpuffer: Bytestring <code>Data</code></li>\n<li>Konfigurationsparameter / Offsets: <code>Offset</code>, <code>PXXCOUNTER_POS</code>, <code>PXXCOUNTER_LEN</code></li>\n<li>Notizen / Kommentare:</li>\n<li>Profil-Platzhaltererklärung: <code>\"XX\" indicates one specific E2E profile. Placeholders are defined on profile level.</code></li>\n<li>Speicherbereichsdefinition: <code>Parameter State-&gt; Counter has length PXXCOUNTER_LEN (in bytes). Bytes need to be stored in Data at positions Offset + PXXCOUNTER_POS to Offset + PXXCOUNTER_POS + PXXCOUNTER_LEN - 1.</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Start über den Initialknoten (Initial Node).</li>\n<li>Übergang zum Aktionsknoten <code>Copy parameter State-&gt;Counter to bytstring Data in Big Endian order.</code>: Der Zählerwert aus <code>State-&gt;Counter</code> wird byteweise in Big-Endian-Reihenfolge in das Bytestring <code>Data</code> kopiert. Die Zielpositionen erstrecken sich über den zusammenhängenden Indexbereich <code>Offset + PXXCOUNTER_POS</code> bis <code>Offset + PXXCOUNTER_POS + PXXCOUNTER_LEN - 1</code>.</li>\n<li>Direkter Übergang zum Endknoten (Activity Final Node).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorschrift gemäß Anforderung [PRS_E2E_02365] (zugehörig zu RS_E2E_08539). Für Entwickler von E2E-Treiber- und Plattformroutinen ist zwingend die Big-Endian-Bytereihenfolge bei der Serialisierung des Counters zu beachten, unabhängig von der nativen Byteorder der Host-CPU. Der Platzhalter <code>XX</code> steht für das jeweilige konkrete Profil (z. B. 01, 02, etc.), dessen profilbezogene Konstanten (<code>PXXCOUNTER_POS</code>, <code>PXXCOUNTER_LEN</code>) sowie der anwenderspezifische Basis-Offset (<code>Offset</code>) die genaue Byte-Position im Puffer <code>Data</code> determinieren.</p>"}], "trans": [{"from": "FIG-7b8398836d955876", "to": "FIG-3d8050c7c1ecb539", "fr": "R21-11", "tr": "R22-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Aktionsknoten: Text von „Copy parameter State->Counter to bytestring Data in Big Endian order“ zu „Copy parameter State->Counter to bytstring Data in Big Endian order.“ geändert (Tippfehler „bytstring“ und hinzugefügter Schlusspunkt).</li>\n<li>Obere Notiz: Text von „Placeholder are defined on profile level.“ zu „Placeholders are defined on profile level.“ korrigiert (Pluralform).</li>\n<li>Untere Notiz: Position von rechts unterhalb des Aktionsknotens nach links unterhalb verschoben; Pfeil-Darstellung von „State -> Counter“ zu „State-> Counter“ vereinheitlicht.</li>\n</ul>"}]};
